// === Tab: mySketch ===
var nmobiles=5000;
var mobiles=[];
var a1, a2, a3, a4, amax;
var speed = 10;
var trailmult = 3;
var change=0.01;
var respawnprop=0.01;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0);
  noFill();  
  colorMode(HSB, 360, 255, 255, 255);
  strokeWeight(1.0);
  reset();
}
function reset() {
  amax=random(5);
  a1=random(1, amax);
  a2=random(1, amax);
  a3=random(1, amax);
  a4=random(1, amax);
  for (var i = 0; i < nmobiles; i++) {
    mobiles[i] = new Mobile(i);
  }
}
function draw() {
	background(0);
  for (var i = 0; i < nmobiles; i++) {
    mobiles[i].run();
  }
  a1+=random(-change, change);
  a2+=random(-change, change);
  a3+=random(-change, change);
  a4+=random(-change, change);
}
function keyReleased() {
  if (key=="s" || key=="S")save("svimg" + day() + "_" + month() + "_" + hour() + "_" + minute() + "_" + second() + ".jpg");
  if (keyCode==32) reset();
  if(key=="r" || key=="R")setup();
}

function Mobile(index) {
  this.index=index;
  this.velocity=createVector(0, 0);
  this.acceleration=createVector(0, 0);
  this.position=createVector(random(0, width), random(0, height));
  this.trans=random(100, 250);
	this.state = 0; // 0-9:init 10:normal 11+:fade
}



// Method to update position and draw
Mobile.prototype.run = function() {
  this.velocity=createVector(
			1-2*noise(a4+a2*sin(PI*this.position.x/width), a4+a2*sin(PI*this.position.y/height)), 
			1-2*noise(a2+a3*cos(PI*this.position.x/width), a4+a3*cos(PI*this.position.y/height)));
  this.velocity.mult(speed);//100*fbm(this.position));
  //this.velocity.rotate(10*noise(a4+a3*sin(PI*this.position.x/width)));

  this.position.add(this.velocity);

  var position0=this.position.copy().add(p5.Vector.mult(this.velocity, -trailmult));

	if (this.state<10) {
		stroke(255,this.trans*this.state/10);	
		this.state++;
	}
	else if (this.state>10) {
		stroke(255,this.trans*(20-this.state)/10);	
		this.state++;
	}
	else {
		stroke(255,this.trans);
		if (random(0,1)<respawnprop) {
			this.state = 11;
		}
	}
  line(position0.x, position0.y, this.position.x, this.position.y);
  if (this.position.x>width || this.position.x<0 || this.position.y>height || this.position.y<0 || this.state>20) {
    this.position0=createVector(random(0, width), random(0, height));
    this.position=this.position0.copy();
		this.state=0;
  }
};

